"use client"

import * as React from "react"
import {
  ArrowLeft,
  ArrowRight,
  Columns3,
  ExternalLink,
  Filter,
  Grid3X3,
  Image,
  List,
  Search,
  X,
} from "lucide-react"

import { cn } from "@/lib/utils"
import type { ViewerSource } from "@/lib/viewer-source"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { FileViewer } from "@/components/ui/file-viewer"
import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"

import { FileSystemColumnsView } from "./file-system-columns-view"
import { useFileSystemController } from "./file-system-controller"
import { FileSystemGalleryView } from "./file-system-gallery-view"
import { FileSystemGridView } from "./file-system-grid-view"
import { pathName } from "./file-system-index"
import { FileSystemListView } from "./file-system-list-view"
import { FileSystemPreview } from "./file-system-preview"
import {
  dateModifiedFilterLabel,
  getFileSystemCategoryLabel,
  normalizeFileSystemSearch,
} from "./file-system-query"
import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemProps,
  FileSystemView,
} from "./file-system-types"

export type {
  FileSystemFileItem,
  FileSystemFolderItem,
  FileSystemItem,
  FileSystemLoadChildrenArgs,
  FileSystemLoadChildrenResult,
  FileSystemProps,
  FileSystemResolveSourceArgs,
  FileSystemView,
} from "./file-system-types"

const VIEW_OPTIONS: Array<{
  icon: React.ComponentType<{ className?: string }>
  label: string
  value: FileSystemView
}> = [
  { icon: List, label: "List", value: "list" },
  { icon: Grid3X3, label: "Grid", value: "grid" },
  { icon: Columns3, label: "Columns", value: "columns" },
  { icon: Image, label: "Gallery", value: "gallery" },
]

export function FileSystem({
  items,
  className,
  defaultPath,
  defaultSelectedPath,
  defaultView = "list",
  loadChildren,
  onFileOpen,
  onSelectionChange,
  onViewChange,
  renderFileActions,
  renderMetadata,
  resolveSource,
  selectedPath,
  title = "Files",
  view,
}: FileSystemProps) {
  const controller = useFileSystemController({
    defaultPath,
    defaultSelectedPath,
    defaultView,
    items,
    loadChildren,
    onSelectionChange,
    onViewChange,
    resolveSource,
    selectedPath,
    view,
  })
  const [openedFile, setOpenedFile] = React.useState<{
    file: FileSystemFileEntry
    source: ViewerSource | null
  } | null>(null)

  const openFile = React.useCallback(
    (file: FileSystemFileEntry) => {
      const controller_ = new AbortController()

      void controller
        .resolveFileSource(file, controller_.signal)
        .then((source) => {
          if (onFileOpen) {
            onFileOpen(file, source)
            return
          }
          setOpenedFile({ file, source })
        })
        .catch(() => {
          if (onFileOpen) {
            onFileOpen(file, null)
          } else {
            setOpenedFile({ file, source: null })
          }
        })
    },
    [controller, onFileOpen]
  )

  const selectedFile =
    controller.selectedEntry?.kind === "file" ? controller.selectedEntry : null
  const currentFolderName =
    controller.currentPath === ""
      ? title
      : pathName(controller.currentPath) || title
  const itemCount = controller.currentEntries.length
  const isSearching =
    normalizeFileSystemSearch(controller.query.search).length > 0
  const hasFilters =
    controller.query.filters.categories.length > 0 ||
    controller.query.filters.updatedAfter !== null

  return (
    <section
      data-slot="file-system"
      className={cn(
        "flex h-[640px] min-h-0 overflow-hidden rounded-lg border bg-background text-foreground",
        className
      )}
    >
      <div className="flex min-w-0 flex-1 flex-col">
        <div className="flex h-12 shrink-0 items-center gap-2 border-b bg-muted/35 px-2">
          <div className="flex min-w-0 flex-1 items-center gap-1">
            <Button
              aria-label="Back"
              disabled={!controller.canGoBack}
              onClick={controller.goBack}
              size="icon-sm"
              variant="ghost"
            >
              <ArrowLeft className="size-4" aria-hidden />
            </Button>
            <Button
              aria-label="Forward"
              disabled={!controller.canGoForward}
              onClick={controller.goForward}
              size="icon-sm"
              variant="ghost"
            >
              <ArrowRight className="size-4" aria-hidden />
            </Button>
            <div className="min-w-0 px-1">
              <div className="truncate text-sm font-semibold">
                {currentFolderName}
              </div>
              <div className="truncate text-xs text-muted-foreground">
                {controller.currentPath || "/"}
              </div>
            </div>
          </div>
          <Tabs
            value={controller.view}
            onValueChange={(nextView) =>
              controller.setView(nextView as FileSystemView)
            }
            className="hidden gap-0 md:flex"
          >
            <TabsList className="h-8 p-0.5">
              {VIEW_OPTIONS.map((option) => (
                <TabsTrigger
                  key={option.value}
                  value={option.value}
                  aria-label={`${option.label} view`}
                  title={`${option.label} view`}
                  className="h-7 px-2"
                >
                  <option.icon className="size-4" aria-hidden />
                </TabsTrigger>
              ))}
            </TabsList>
          </Tabs>
          <div className="relative w-52 min-w-0 max-sm:w-36">
            <Search
              className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground"
              aria-hidden
            />
            <Input
              aria-label="Search files"
              className="[&_input]:pl-7"
              nativeInput
              onChange={(event) => controller.setSearch(event.target.value)}
              placeholder="Search"
              size="sm"
              type="search"
              value={controller.query.search}
            />
          </div>
        </div>
        {controller.categories.length ? (
          <div className="flex shrink-0 items-center gap-1 overflow-x-auto border-b px-2 py-1.5">
            <Filter className="size-3.5 shrink-0 text-muted-foreground" />
            {controller.categories.map((category) => {
              const isActive =
                controller.query.filters.categories.includes(category)

              return (
                <button
                  key={category}
                  type="button"
                  onClick={() => controller.toggleCategory(category)}
                  className={cn(
                    "h-6 shrink-0 rounded-md border px-2 text-xs outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring",
                    isActive
                      ? "border-primary bg-primary text-primary-foreground"
                      : "border-input bg-background text-muted-foreground"
                  )}
                >
                  {getFileSystemCategoryLabel(category)}
                </button>
              )
            })}
            {(["last7", "last30"] as const).map((preset) => {
              const isActive = controller.query.filters.updatedAfter === preset

              return (
                <button
                  key={preset}
                  type="button"
                  onClick={() => controller.setModifiedAfter(preset)}
                  className={cn(
                    "h-6 shrink-0 rounded-md border px-2 text-xs outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring",
                    isActive
                      ? "border-primary bg-primary text-primary-foreground"
                      : "border-input bg-background text-muted-foreground"
                  )}
                >
                  {dateModifiedFilterLabel(preset)}
                </button>
              )
            })}
            {hasFilters ? (
              <Button
                size="xs"
                variant="ghost"
                onClick={controller.clearFilters}
              >
                <X className="size-3" aria-hidden />
                Clear
              </Button>
            ) : null}
          </div>
        ) : null}
        <div className="min-h-0 flex-1">
          {controller.view === "list" ? (
            <FileSystemListView controller={controller} onOpenFile={openFile} />
          ) : controller.view === "grid" ? (
            <FileSystemGridView controller={controller} onOpenFile={openFile} />
          ) : controller.view === "columns" ? (
            <FileSystemColumnsView
              controller={controller}
              onOpenFile={openFile}
            />
          ) : (
            <FileSystemGalleryView
              controller={controller}
              onOpenFile={openFile}
              renderFileActions={renderFileActions}
              renderMetadata={renderMetadata}
            />
          )}
        </div>
        <div
          aria-live="polite"
          className="flex h-8 shrink-0 items-center justify-between gap-3 border-t bg-muted/35 px-3 text-xs text-muted-foreground"
        >
          <span>
            {itemCount}{" "}
            {isSearching || hasFilters
              ? itemCount === 1
                ? "result"
                : "results"
              : itemCount === 1
                ? "item"
                : "items"}
          </span>
          {controller.selectedEntry ? (
            <span className="min-w-0 truncate">
              {controller.selectedEntry.name} selected
            </span>
          ) : null}
        </div>
      </div>
      {controller.view !== "gallery" ? (
        <FileSystemPreview
          entry={controller.selectedEntry}
          renderFileActions={renderFileActions}
          renderMetadata={renderMetadata}
          resolveFileSource={controller.resolveFileSource}
          className="hidden w-[42%] max-w-xl min-w-[22rem] lg:flex"
        />
      ) : null}
      <Dialog
        open={openedFile !== null}
        onOpenChange={(open) => {
          if (!open) setOpenedFile(null)
        }}
      >
        {openedFile ? (
          <DialogContent className="h-[88vh] max-w-[min(96vw,1280px)] overflow-hidden p-0">
            <DialogHeader className="shrink-0 border-b px-4 py-3">
              <div className="flex min-w-0 items-center gap-3 pr-8">
                <DialogTitle className="truncate text-base">
                  {openedFile.file.name}
                </DialogTitle>
                {openedFile.source?.kind === "url" ? (
                  <Button
                    render={
                      <a
                        href={openedFile.source.url}
                        target="_blank"
                        rel="noreferrer"
                      />
                    }
                    size="xs"
                    variant="outline"
                  >
                    <ExternalLink className="size-3.5" aria-hidden />
                    Open
                  </Button>
                ) : null}
              </div>
            </DialogHeader>
            <div className="min-h-0 flex-1">
              {openedFile.source ? (
                <FileSystemPreviewDialog source={openedFile.source} />
              ) : (
                <div className="flex size-full items-center justify-center text-sm text-muted-foreground">
                  Preview unavailable
                </div>
              )}
            </div>
          </DialogContent>
        ) : null}
      </Dialog>
    </section>
  )
}

function FileSystemPreviewDialog({ source }: { source: ViewerSource }) {
  return (
    <ScrollArea>
      <div className="h-[calc(88vh-4rem)] min-h-0">
        <FileSystemDialogViewer source={source} />
      </div>
    </ScrollArea>
  )
}

function FileSystemDialogViewer({ source }: { source: ViewerSource }) {
  return <FileViewer source={source} bare className="size-full min-h-0" />
}

import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemFolderEntry,
  FileSystemIndex,
  FileSystemItem,
} from "./file-system-types"

export function normalizeFolderPath(path: string | undefined | null): string {
  if (!path || path === "/") return ""
  const trimmed = path.replace(/^\/+/, "")
  return trimmed.endsWith("/") ? trimmed : `${trimmed}/`
}

export function normalizeFilePath(path: string): string {
  return path.replace(/^\/+/, "").replace(/\/+$/, "")
}

export function pathName(path: string): string {
  const trimmed = path.endsWith("/") ? path.slice(0, -1) : path
  const separatorIndex = trimmed.lastIndexOf("/")
  return separatorIndex === -1 ? trimmed : trimmed.slice(separatorIndex + 1)
}

export function pathParent(path: string): string {
  const trimmed = path.endsWith("/") ? path.slice(0, -1) : path
  const separatorIndex = trimmed.lastIndexOf("/")
  return separatorIndex === -1 ? "" : `${trimmed.slice(0, separatorIndex)}/`
}

export function buildFileSystemIndex(items: readonly FileSystemItem[]) {
  const folders = new Map<string, FileSystemFolderEntry>()
  const files = new Map<string, FileSystemFileEntry>()

  const ensureFolderChain = (folderPath: string) => {
    let path = normalizeFolderPath(folderPath)

    while (path && !folders.has(path)) {
      folders.set(path, {
        kind: "folder",
        name: pathName(path),
        parentPath: pathParent(path),
        path,
      })
      path = pathParent(path)
    }
  }

  for (const item of items) {
    if (item.kind === "folder") {
      const path = normalizeFolderPath(item.path)
      if (!path) continue

      folders.set(path, {
        ...item,
        name: item.name ?? pathName(path),
        parentPath: normalizeFolderPath(item.parentPath ?? pathParent(path)),
        path,
      })
      ensureFolderChain(pathParent(path))
      continue
    }

    const path = normalizeFilePath(item.path)
    if (!path) continue

    files.set(path, {
      ...item,
      key: item.key ?? path,
      name: item.name ?? pathName(path),
      parentPath: normalizeFolderPath(item.parentPath ?? pathParent(path)),
      path,
    })
    ensureFolderChain(pathParent(path))
  }

  const children = new Map<string, FileSystemEntry[]>()
  const pushChild = (entry: FileSystemEntry) => {
    const siblings = children.get(entry.parentPath)

    if (siblings) {
      siblings.push(entry)
    } else {
      children.set(entry.parentPath, [entry])
    }
  }

  for (const folder of folders.values()) pushChild(folder)
  for (const file of files.values()) pushChild(file)
  for (const siblings of children.values()) siblings.sort(compareEntryNames)

  deriveFolderModifiedDates({ children, files, folders })

  return { children, files, folders } satisfies FileSystemIndex
}

export function compareEntryNames(
  left: Pick<FileSystemEntry, "kind" | "name">,
  right: Pick<FileSystemEntry, "kind" | "name">
) {
  if (left.kind !== right.kind) return left.kind === "folder" ? -1 : 1
  return left.name.localeCompare(right.name, undefined, {
    numeric: true,
    sensitivity: "base",
  })
}

export function folderHasChildren(
  index: FileSystemIndex,
  folder: FileSystemFolderEntry
) {
  return (
    folder.hasChildren === true ||
    (index.children.get(folder.path)?.length ?? 0) > 0
  )
}

function deriveFolderModifiedDates(index: FileSystemIndex) {
  const foldersDeepestFirst = [...index.folders.values()].sort(
    (left, right) => right.path.length - left.path.length
  )

  for (const folder of foldersDeepestFirst) {
    if (folder.updatedAt) continue

    let newestTime = Number.NEGATIVE_INFINITY
    let newestValue: string | undefined

    for (const child of index.children.get(folder.path) ?? []) {
      const value = child.updatedAt ?? child.createdAt
      const time = value ? Date.parse(value) : Number.NaN

      if (!Number.isNaN(time) && time > newestTime) {
        newestTime = time
        newestValue = value
      }
    }

    if (newestValue) folder.updatedAt = newestValue
  }
}

import { detectCategory } from "@/lib/viewer-source"

import { compareEntryNames } from "./file-system-index"
import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemFilterState,
  FileSystemIndex,
  FileSystemQueryState,
  FileSystemSortState,
  FileSystemTreeRow,
} from "./file-system-types"

export const DEFAULT_FILE_SYSTEM_SORT: FileSystemSortState = {
  direction: "asc",
  key: "name",
}

export function normalizeFileSystemSearch(value: string): string {
  return value.trim().toLowerCase()
}

export function getFileSystemCategory(file: FileSystemFileEntry) {
  return detectCategory(file.name, file.mimeType)
}

export function getFileSystemCategoryLabel(category: string) {
  switch (category) {
    case "csv":
      return "CSV"
    case "docx":
      return "Word"
    case "html":
      return "HTML"
    case "image":
      return "Image"
    case "markdown":
      return "Markdown"
    case "pdf":
      return "PDF"
    case "pptx":
      return "PowerPoint"
    case "text":
      return "Text"
    case "xlsx":
      return "Excel"
    default:
      return "Unsupported"
  }
}

export function fileMatchesQuery(
  file: FileSystemFileEntry,
  query: FileSystemQueryState
) {
  const search = normalizeFileSystemSearch(query.search)
  if (
    search &&
    !file.path.toLowerCase().includes(search) &&
    !file.name.toLowerCase().includes(search)
  ) {
    return false
  }

  if (
    query.filters.categories.length &&
    !query.filters.categories.includes(getFileSystemCategory(file))
  ) {
    return false
  }

  const cutoff = dateModifiedCutoff(query.filters.updatedAfter)
  if (cutoff) {
    const fileTime = Date.parse(file.updatedAt ?? file.createdAt ?? "")

    if (Number.isNaN(fileTime) || fileTime < cutoff.getTime()) return false
  }

  return true
}

export function deriveVisibleIndex(
  index: FileSystemIndex,
  currentPath: string,
  query: FileSystemQueryState
): FileSystemIndex {
  const search = normalizeFileSystemSearch(query.search)
  const hasCategoryFilter = query.filters.categories.length > 0
  const hasDateFilter = query.filters.updatedAfter !== null

  if (!search && !hasCategoryFilter && !hasDateFilter)
    return sortFileSystemIndex(index, query.sort)

  const visiblePaths = new Set<string>()
  const markVisible = (path: string) => {
    let nextPath = path

    while (
      nextPath &&
      nextPath !== currentPath &&
      !visiblePaths.has(nextPath)
    ) {
      visiblePaths.add(nextPath)
      const trimmed = nextPath.endsWith("/") ? nextPath.slice(0, -1) : nextPath
      const separatorIndex = trimmed.lastIndexOf("/")

      nextPath =
        separatorIndex === -1 ? "" : `${trimmed.slice(0, separatorIndex)}/`
    }
  }

  for (const [path, file] of index.files) {
    if (currentPath && !path.startsWith(currentPath)) continue
    if (!fileMatchesQuery(file, query)) continue
    visiblePaths.add(path)
    markVisible(file.parentPath)
  }

  if (!hasCategoryFilter) {
    for (const [path, folder] of index.folders) {
      if (currentPath && !path.startsWith(currentPath)) continue
      if (
        search &&
        !path.toLowerCase().includes(search) &&
        !folder.name.toLowerCase().includes(search)
      ) {
        continue
      }
      visiblePaths.add(path)
      markVisible(folder.parentPath)
    }
  }

  const children = new Map<string, FileSystemEntry[]>()

  for (const [parentPath, entries] of index.children) {
    const visibleEntries = entries.filter((entry) =>
      visiblePaths.has(entry.path)
    )
    if (visibleEntries.length) children.set(parentPath, visibleEntries)
  }

  return sortFileSystemIndex({ ...index, children }, query.sort)
}

export function sortFileSystemIndex(
  index: FileSystemIndex,
  sort: FileSystemSortState
) {
  if (
    sort.key === DEFAULT_FILE_SYSTEM_SORT.key &&
    sort.direction === DEFAULT_FILE_SYSTEM_SORT.direction
  ) {
    return index
  }

  const children = new Map<string, FileSystemEntry[]>()

  for (const [parentPath, entries] of index.children) {
    children.set(
      parentPath,
      [...entries].sort((left, right) => compareEntries(left, right, sort))
    )
  }

  return { ...index, children } satisfies FileSystemIndex
}

export function compareEntries(
  left: FileSystemEntry,
  right: FileSystemEntry,
  sort: FileSystemSortState
) {
  if (left.kind !== right.kind) return left.kind === "folder" ? -1 : 1

  let result = 0

  switch (sort.key) {
    case "kind":
      result = entryKindLabel(left).localeCompare(entryKindLabel(right))
      break
    case "size":
      result = (entrySize(left) ?? -1) - (entrySize(right) ?? -1)
      break
    case "updatedAt":
      result = entryTime(left) - entryTime(right)
      break
    case "name":
      result = compareEntryNames(left, right)
      break
  }

  if (result === 0) result = compareEntryNames(left, right)
  return sort.direction === "asc" ? result : -result
}

export function flattenFileSystemRows({
  currentPath,
  expandedPaths,
  index,
}: {
  currentPath: string
  expandedPaths: ReadonlySet<string>
  index: FileSystemIndex
}): FileSystemTreeRow[] {
  const rows: FileSystemTreeRow[] = []

  const walk = (folderPath: string, depth: number) => {
    for (const entry of index.children.get(folderPath) ?? []) {
      rows.push({ depth, entry })
      if (entry.kind === "folder" && expandedPaths.has(entry.path)) {
        walk(entry.path, depth + 1)
      }
    }
  }

  walk(currentPath, 0)
  return rows
}

export function collectFileSystemCategories(index: FileSystemIndex) {
  const categories = new Set<string>()

  for (const file of index.files.values()) {
    categories.add(getFileSystemCategory(file))
  }

  return [...categories].sort((left, right) =>
    getFileSystemCategoryLabel(left).localeCompare(
      getFileSystemCategoryLabel(right)
    )
  )
}

export function entryKindLabel(entry: FileSystemEntry) {
  return entry.kind === "folder"
    ? "Folder"
    : getFileSystemCategoryLabel(getFileSystemCategory(entry))
}

function entrySize(entry: FileSystemEntry) {
  return entry.kind === "file" ? entry.size : undefined
}

function entryTime(entry: FileSystemEntry) {
  const time = Date.parse(entry.updatedAt ?? entry.createdAt ?? "")
  return Number.isNaN(time) ? Number.NEGATIVE_INFINITY : time
}

export function fileSystemFilterIsEmpty(filters: FileSystemFilterState) {
  return filters.categories.length === 0 && filters.updatedAfter === null
}

export function dateModifiedCutoff(
  preset: FileSystemFilterState["updatedAfter"]
) {
  if (!preset) return null

  const cutoff = new Date()
  cutoff.setDate(cutoff.getDate() - (preset === "last7" ? 7 : 30))
  return cutoff
}

export function dateModifiedFilterLabel(
  preset: FileSystemFilterState["updatedAfter"]
) {
  if (preset === "last7") return "Modified 7d"
  if (preset === "last30") return "Modified 30d"
  return "Modified"
}

"use client"

import * as React from "react"

import type { ViewerSource } from "@/lib/viewer-source"

import { buildFileSystemIndex, normalizeFolderPath } from "./file-system-index"
import {
  collectFileSystemCategories,
  DEFAULT_FILE_SYSTEM_SORT,
  deriveVisibleIndex,
  fileMatchesQuery,
  fileSystemFilterIsEmpty,
} from "./file-system-query"
import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemItem,
  FileSystemLoadChildrenResult,
  FileSystemProps,
  FileSystemQueryState,
  FileSystemSortKey,
  FileSystemView,
} from "./file-system-types"

export type FileSystemController = ReturnType<typeof useFileSystemController>

export function useFileSystemController({
  items,
  defaultPath = "",
  defaultSelectedPath = null,
  defaultView = "list",
  loadChildren,
  onSelectionChange,
  onViewChange,
  resolveSource,
  selectedPath: selectedPathProp,
  view: viewProp,
}: Pick<
  FileSystemProps,
  | "items"
  | "defaultPath"
  | "defaultSelectedPath"
  | "defaultView"
  | "loadChildren"
  | "onSelectionChange"
  | "onViewChange"
  | "resolveSource"
  | "selectedPath"
  | "view"
>) {
  const [loadedItems, setLoadedItems] = React.useState<FileSystemItem[]>([])
  const allItems = React.useMemo(
    () => (loadedItems.length ? [...items, ...loadedItems] : items),
    [items, loadedItems]
  )
  const rawIndex = React.useMemo(
    () => buildFileSystemIndex(allItems),
    [allItems]
  )
  const [query, setQuery] = React.useState<FileSystemQueryState>({
    filters: { categories: [], updatedAfter: null },
    search: "",
    sort: DEFAULT_FILE_SYSTEM_SORT,
  })
  const [history, setHistory] = React.useState(() => ({
    index: 0,
    stack: [normalizeFolderPath(defaultPath)],
  }))
  const currentPath = history.stack[history.index] ?? ""
  const visibleIndex = React.useMemo(
    () => deriveVisibleIndex(rawIndex, currentPath, query),
    [currentPath, query, rawIndex]
  )

  const [internalView, setInternalView] =
    React.useState<FileSystemView>(defaultView)
  const view = viewProp ?? internalView
  const setView = React.useCallback(
    (nextView: FileSystemView) => {
      setInternalView(nextView)
      onViewChange?.(nextView)
    },
    [onViewChange]
  )

  const isSelectionControlled = selectedPathProp !== undefined
  const [internalSelectedPath, setInternalSelectedPath] = React.useState<
    string | null
  >(defaultSelectedPath)
  const selectedPath = isSelectionControlled
    ? (selectedPathProp ?? null)
    : internalSelectedPath
  const selectedEntry = React.useMemo(() => {
    if (!selectedPath) return null
    return (
      rawIndex.files.get(selectedPath) ??
      rawIndex.folders.get(normalizeFolderPath(selectedPath)) ??
      null
    )
  }, [rawIndex, selectedPath])

  const selectEntry = React.useCallback(
    (entry: FileSystemEntry | null) => {
      if (!isSelectionControlled) setInternalSelectedPath(entry?.path ?? null)
      onSelectionChange?.(entry)
    },
    [isSelectionControlled, onSelectionChange]
  )

  React.useEffect(() => {
    if (
      !selectedEntry ||
      (!query.search && fileSystemFilterIsEmpty(query.filters))
    ) {
      return
    }
    if (
      selectedEntry.kind === "file" &&
      fileMatchesQuery(selectedEntry, query)
    ) {
      return
    }
    if (selectedEntry.kind === "folder") {
      const visible = visibleIndex.folders.has(selectedEntry.path)
      if (visible) return
    }
    selectEntry(null)
  }, [query, selectEntry, selectedEntry, visibleIndex.folders])

  const [expandedPaths, setExpandedPaths] = React.useState<Set<string>>(
    () => new Set()
  )
  const [loadingFolders, setLoadingFolders] = React.useState<Set<string>>(
    () => new Set()
  )
  const [folderErrors, setFolderErrors] = React.useState(
    new Map<string, string>()
  )
  const folderRequests = React.useRef(new Map<string, AbortController>())
  const sourceCache = React.useRef(new Map<string, ViewerSource | null>())

  React.useEffect(() => {
    const requests = folderRequests.current

    return () => {
      for (const controller of requests.values()) {
        controller.abort()
      }
    }
  }, [])

  const setSearch = React.useCallback((search: string) => {
    setQuery((previous) => ({ ...previous, search }))
  }, [])

  const setSortKey = React.useCallback((key: FileSystemSortKey) => {
    setQuery((previous) => ({
      ...previous,
      sort:
        previous.sort.key === key
          ? {
              direction: previous.sort.direction === "asc" ? "desc" : "asc",
              key,
            }
          : {
              direction: key === "name" || key === "kind" ? "asc" : "desc",
              key,
            },
    }))
  }, [])

  const toggleCategory = React.useCallback((category: string) => {
    setQuery((previous) => {
      const categories = previous.filters.categories.includes(category)
        ? previous.filters.categories.filter((entry) => entry !== category)
        : [...previous.filters.categories, category]

      return {
        ...previous,
        filters: { ...previous.filters, categories },
      }
    })
  }, [])

  const setModifiedAfter = React.useCallback(
    (updatedAfter: FileSystemQueryState["filters"]["updatedAfter"]) => {
      setQuery((previous) => ({
        ...previous,
        filters: {
          ...previous.filters,
          updatedAfter:
            previous.filters.updatedAfter === updatedAfter
              ? null
              : updatedAfter,
        },
      }))
    },
    []
  )

  const clearFilters = React.useCallback(() => {
    setQuery((previous) => ({
      ...previous,
      filters: { categories: [], updatedAfter: null },
    }))
  }, [])

  const toggleExpanded = React.useCallback((path: string) => {
    setExpandedPaths((previous) => {
      const next = new Set(previous)

      if (next.has(path)) {
        next.delete(path)
      } else {
        next.add(path)
      }

      return next
    })
  }, [])

  const ensureChildren = React.useCallback(
    async (path: string, { retry = false }: { retry?: boolean } = {}) => {
      const folderPath = normalizeFolderPath(path)
      const folder = rawIndex.folders.get(folderPath)

      if (!loadChildren || !folder?.hasChildren) return
      if (!retry && (rawIndex.children.get(folderPath)?.length ?? 0) > 0) return
      if (folderRequests.current.has(folderPath)) return

      const controller = new AbortController()

      folderRequests.current.set(folderPath, controller)
      setLoadingFolders((previous) => new Set(previous).add(folderPath))
      setFolderErrors((previous) => {
        const next = new Map(previous)

        next.delete(folderPath)
        return next
      })

      try {
        let cursor: string | null = null
        const nextItems: FileSystemItem[] = []

        do {
          const result: FileSystemLoadChildrenResult = await loadChildren({
            cursor,
            path: folderPath,
            signal: controller.signal,
          })

          nextItems.push(...result.items)
          cursor = result.nextCursor ?? null
        } while (cursor && !controller.signal.aborted)

        if (!controller.signal.aborted && nextItems.length) {
          setLoadedItems((previous) => [...previous, ...nextItems])
        }
      } catch (error) {
        if (!controller.signal.aborted) {
          setFolderErrors((previous) =>
            new Map(previous).set(folderPath, errorMessage(error))
          )
        }
      } finally {
        folderRequests.current.delete(folderPath)
        setLoadingFolders((previous) => {
          const next = new Set(previous)

          next.delete(folderPath)
          return next
        })
      }
    },
    [loadChildren, rawIndex.children, rawIndex.folders]
  )

  const navigateTo = React.useCallback(
    (path: string) => {
      const folderPath = normalizeFolderPath(path)

      setHistory((previous) => {
        if (previous.stack[previous.index] === folderPath) return previous

        const stack = [
          ...previous.stack.slice(0, previous.index + 1),
          folderPath,
        ]

        return { index: stack.length - 1, stack }
      })
      setSearch("")
      selectEntry(null)
      void ensureChildren(folderPath)
    },
    [ensureChildren, selectEntry, setSearch]
  )

  const goBack = React.useCallback(() => {
    setHistory((previous) => ({
      ...previous,
      index: Math.max(0, previous.index - 1),
    }))
    selectEntry(null)
    setSearch("")
  }, [selectEntry, setSearch])

  const goForward = React.useCallback(() => {
    setHistory((previous) => ({
      ...previous,
      index: Math.min(previous.stack.length - 1, previous.index + 1),
    }))
    selectEntry(null)
    setSearch("")
  }, [selectEntry, setSearch])

  const openEntry = React.useCallback(
    (entry: FileSystemEntry) => {
      if (entry.kind === "folder") {
        navigateTo(entry.path)
      }
    },
    [navigateTo]
  )

  const resolveFileSource = React.useCallback(
    async (file: FileSystemFileEntry, signal: AbortSignal) => {
      if (file.source) return file.source

      const cacheKey = sourceCacheKey(file)

      if (sourceCache.current.has(cacheKey)) {
        return sourceCache.current.get(cacheKey) ?? null
      }
      if (!resolveSource) return null

      const source = await resolveSource({ file, signal })

      if (!signal.aborted) sourceCache.current.set(cacheKey, source)
      return source
    },
    [resolveSource]
  )

  React.useEffect(() => {
    void ensureChildren(currentPath)
  }, [currentPath, ensureChildren])

  const categories = React.useMemo(
    () => collectFileSystemCategories(rawIndex),
    [rawIndex]
  )
  const currentEntries = visibleIndex.children.get(currentPath) ?? []
  const currentFolder =
    currentPath === "" ? null : (rawIndex.folders.get(currentPath) ?? null)

  return {
    canGoBack: history.index > 0,
    canGoForward: history.index < history.stack.length - 1,
    categories,
    clearFilters,
    currentEntries,
    currentFolder,
    currentPath,
    ensureChildren,
    expandedPaths,
    folderErrors,
    goBack,
    goForward,
    index: visibleIndex,
    loadingFolders,
    navigateTo,
    openEntry,
    query,
    rawIndex,
    resolveFileSource,
    selectEntry,
    selectedEntry,
    selectedPath,
    setModifiedAfter,
    setSearch,
    setSortKey,
    setView,
    toggleCategory,
    toggleExpanded,
    view,
  }
}

function sourceCacheKey(file: FileSystemFileEntry) {
  return [file.path, file.key, file.etag ?? "", file.updatedAt ?? ""].join("\0")
}

function errorMessage(error: unknown) {
  if (error instanceof Error && error.message) return error.message
  return "Couldn't load this folder."
}

