import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { Folder } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { FileSystemController } from "./file-system-controller"
import { FileSystemThumbnail } from "./file-system-preview"
import type { FileSystemEntry, FileSystemFileEntry } from "./file-system-types"

const TILE_MIN_WIDTH = 124
const TILE_HEIGHT = 132
const GRID_PADDING = 12

export function FileSystemGridView({
  controller,
  onOpenFile,
}: {
  controller: FileSystemController
  onOpenFile: (file: FileSystemFileEntry) => void
}) {
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const [columnCount, setColumnCount] = React.useState(1)
  const entries = controller.currentEntries

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current
    if (!viewport || typeof ResizeObserver === "undefined") return

    const update = () => {
      const available = Math.max(1, viewport.clientWidth - GRID_PADDING * 2)
      setColumnCount(Math.max(1, Math.floor(available / TILE_MIN_WIDTH)))
    }
    const observer = new ResizeObserver(update)

    update()
    observer.observe(viewport)
    return () => observer.disconnect()
  }, [])

  const rowCount = Math.ceil(entries.length / columnCount)
  const virtualizer = useVirtualizer({
    count: rowCount,
    estimateSize: () => TILE_HEIGHT,
    getScrollElement: () => viewportRef.current,
    overscan: 5,
  })
  const virtualRows = virtualizer.getVirtualItems()
  const renderedRows = virtualRows.length
    ? virtualRows.map((row) => ({ index: row.index, start: row.start }))
    : Array.from({ length: rowCount }, (_, index) => ({
        index,
        start: index * TILE_HEIGHT,
      }))
  const totalSize = virtualRows.length
    ? virtualizer.getTotalSize()
    : rowCount * TILE_HEIGHT

  if (!entries.length) {
    return (
      <div className="flex size-full items-center justify-center text-sm text-muted-foreground">
        This folder is empty
      </div>
    )
  }

  return (
    <ScrollArea
      orientation="vertical"
      viewportRef={viewportRef}
      viewportClassName="p-3"
      viewportProps={{ role: "listbox", "aria-label": "Files" }}
    >
      <div className="relative" style={{ height: totalSize }}>
        {renderedRows.map((row) => {
          const rowEntries = entries.slice(
            row.index * columnCount,
            row.index * columnCount + columnCount
          )

          return (
            <div
              key={row.index}
              className="absolute inset-x-0 grid gap-2"
              style={{
                gridTemplateColumns: `repeat(${columnCount}, minmax(0, 1fr))`,
                transform: `translateY(${row.start}px)`,
              }}
            >
              {rowEntries.map((entry) => (
                <FileSystemGridTile
                  key={entry.path}
                  controller={controller}
                  entry={entry}
                  onOpenFile={onOpenFile}
                />
              ))}
            </div>
          )
        })}
      </div>
    </ScrollArea>
  )
}

function FileSystemGridTile({
  controller,
  entry,
  onOpenFile,
}: {
  controller: FileSystemController
  entry: FileSystemEntry
  onOpenFile: (file: FileSystemFileEntry) => void
}) {
  const isSelected = entry.path === controller.selectedPath

  return (
    <button
      type="button"
      role="option"
      aria-selected={isSelected}
      tabIndex={isSelected || !controller.selectedPath ? 0 : -1}
      onClick={() => controller.selectEntry(entry)}
      onDoubleClick={() => {
        if (entry.kind === "folder") {
          controller.navigateTo(entry.path)
        } else {
          onOpenFile(entry)
        }
      }}
      className="group flex h-[124px] min-w-0 flex-col items-center gap-2 rounded-md p-2 text-center outline-none hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring"
    >
      <span
        className={cn(
          "flex size-16 shrink-0 items-center justify-center rounded-md",
          isSelected && "bg-accent"
        )}
      >
        {entry.kind === "folder" ? (
          <Folder className="size-11 text-sky-500" aria-hidden />
        ) : (
          <FileSystemThumbnail
            file={entry}
            resolveFileSource={controller.resolveFileSource}
            className="w-14"
          />
        )}
      </span>
      <span
        className={cn(
          "line-clamp-2 max-w-full rounded px-1 text-xs leading-tight break-words",
          isSelected && "bg-primary text-primary-foreground"
        )}
      >
        {entry.name}
      </span>
    </button>
  )
}

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { ChevronRight, Folder } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { FileSystemController } from "./file-system-controller"
import { folderHasChildren, pathParent } from "./file-system-index"
import { FileSystemThumbnail } from "./file-system-preview"
import type { FileSystemEntry, FileSystemFileEntry } from "./file-system-types"

const COLUMN_ROW_HEIGHT = 32

export function FileSystemColumnsView({
  controller,
  onOpenFile,
}: {
  controller: FileSystemController
  onOpenFile: (file: FileSystemFileEntry) => void
}) {
  const columnPaths = React.useMemo(() => {
    const paths = [controller.currentPath]
    const selectedPath = controller.selectedPath

    if (!selectedPath?.startsWith(controller.currentPath)) return paths

    const selectedEntry = controller.selectedEntry
    const targetPath =
      selectedEntry?.kind === "folder"
        ? selectedEntry.path
        : (selectedEntry?.parentPath ?? controller.currentPath)
    const relativePath = targetPath.slice(controller.currentPath.length)
    let walkedPath = controller.currentPath

    for (const segment of relativePath.split("/")) {
      if (!segment) continue
      walkedPath = `${walkedPath}${segment}/`
      paths.push(walkedPath)
    }

    return paths
  }, [
    controller.currentPath,
    controller.selectedEntry,
    controller.selectedPath,
  ])

  return (
    <ScrollArea
      orientation="horizontal"
      viewportClassName="overscroll-x-contain"
    >
      <div className="flex h-full min-w-full">
        {columnPaths.map((path, index) => (
          <FileSystemColumn
            key={path || "(root)"}
            controller={controller}
            isLast={index === columnPaths.length - 1}
            onOpenFile={onOpenFile}
            path={path}
          />
        ))}
      </div>
    </ScrollArea>
  )
}

function FileSystemColumn({
  controller,
  isLast,
  onOpenFile,
  path,
}: {
  controller: FileSystemController
  isLast: boolean
  onOpenFile: (file: FileSystemFileEntry) => void
  path: string
}) {
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const entries = controller.index.children.get(path) ?? []
  const virtualizer = useVirtualizer({
    count: entries.length,
    estimateSize: () => COLUMN_ROW_HEIGHT,
    getScrollElement: () => viewportRef.current,
    overscan: 10,
  })
  const virtualRows = virtualizer.getVirtualItems()
  const renderedRows = virtualRows.length
    ? virtualRows.map((row) => ({
        entry: entries[row.index],
        start: row.start,
      }))
    : entries.map((entry, index) => ({
        entry,
        start: index * COLUMN_ROW_HEIGHT,
      }))
  const totalSize = virtualRows.length
    ? virtualizer.getTotalSize()
    : entries.length * COLUMN_ROW_HEIGHT

  return (
    <div
      className={cn("w-64 shrink-0 border-r", isLast && "flex-1")}
      role="listbox"
      aria-label={path || "Files"}
    >
      <div ref={viewportRef} className="h-full overflow-auto p-1.5">
        {entries.length ? (
          <div className="relative" style={{ height: totalSize }}>
            {renderedRows.map(({ entry, start }) => (
              <FileSystemColumnRow
                key={entry.path}
                controller={controller}
                entry={entry}
                onOpenFile={onOpenFile}
                style={{ transform: `translateY(${start}px)` }}
              />
            ))}
          </div>
        ) : (
          <div className="px-2 py-1.5 text-xs text-muted-foreground">
            This folder is empty
          </div>
        )}
      </div>
    </div>
  )
}

function FileSystemColumnRow({
  controller,
  entry,
  onOpenFile,
  style,
}: {
  controller: FileSystemController
  entry: FileSystemEntry
  onOpenFile: (file: FileSystemFileEntry) => void
  style: React.CSSProperties
}) {
  const isSelected = entry.path === controller.selectedPath
  const isOnTrail =
    entry.kind === "folder" &&
    controller.selectedPath?.startsWith(entry.path) &&
    pathParent(controller.selectedPath) !== entry.parentPath

  return (
    <button
      type="button"
      role="option"
      aria-selected={isSelected}
      tabIndex={isSelected || !controller.selectedPath ? 0 : -1}
      onClick={() => {
        controller.selectEntry(entry)
        if (entry.kind === "folder") void controller.ensureChildren(entry.path)
      }}
      onDoubleClick={() => {
        if (entry.kind === "folder") {
          controller.navigateTo(entry.path)
        } else {
          onOpenFile(entry)
        }
      }}
      className={cn(
        "absolute inset-x-0 flex h-8 shrink-0 items-center gap-2 rounded-md px-2 text-left text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring",
        isSelected
          ? "bg-primary text-primary-foreground"
          : isOnTrail
            ? "bg-accent"
            : "hover:bg-accent/50"
      )}
      style={style}
    >
      {entry.kind === "folder" ? (
        <Folder className="size-4 shrink-0 text-sky-500" aria-hidden />
      ) : (
        <FileSystemThumbnail
          file={entry}
          resolveFileSource={controller.resolveFileSource}
          className="w-4 shrink-0"
        />
      )}
      <span className="min-w-0 flex-1 truncate">{entry.name}</span>
      {entry.kind === "folder" &&
      folderHasChildren(controller.rawIndex, entry) ? (
        <ChevronRight className="size-3.5 shrink-0 text-muted-foreground" />
      ) : null}
    </button>
  )
}

